    select 1 from generate_series(1, 8) s
    where not exists (
      select 1 from public.gps_geofences g
      where g.sector_id = s and g.is_active
    )
  ) then
    raise notice 'gps_geofences: القواطع الثمانية موجودة — لا بذر';
    return;
